FString GeometryScriptUtils::InspectWorldMeshes()
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld) throw std::runtime_error("Stopped editor world required"); const auto* World=GEditor->GetEditorWorldContext().World(); if(!IsValid(World) || World->WorldType!=EWorldType::Editor) throw std::runtime_error("Current editor world unavailable"); FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("world_path"),World->GetPathName()); J->WriteArrayStart(TEXT("components")); int32 Count=0;
 for(TObjectIterator<UDynamicMeshComponent> It;It;++It) { auto* Component=*It; if(!IsValid(Component) || Component->IsTemplate() || Component->GetWorld()!=World) continue; if(Count++>=128) continue; const auto* Mesh=Component->GetDynamicMesh(); J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),Component->GetPathName()); J->WriteValue(TEXT("actor_path"),GetPathNameSafe(Component->GetOwner())); J->WriteValue(TEXT("class_path"),Component->GetClass()->GetPathName()); J->WriteValue(TEXT("registered"),Component->IsRegistered()); J->WriteValue(TEXT("mesh_path"),GetPathNameSafe(Mesh)); J->WriteValue(TEXT("mesh_valid"),IsValid(Mesh)); if(IsValid(Mesh)) Mesh->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { J->WriteValue(TEXT("vertex_count"),Data.VertexCount()); J->WriteValue(TEXT("triangle_count"),Data.TriangleCount()); J->WriteValue(TEXT("edge_count"),Data.EdgeCount()); J->WriteValue(TEXT("max_vertex_id"),Data.MaxVertexID()); J->WriteValue(TEXT("max_triangle_id"),Data.MaxTriangleID()); J->WriteValue(TEXT("compact"),Data.IsCompact()); J->WriteValue(TEXT("has_attributes"),Data.HasAttributes()); J->WriteValue(TEXT("has_vertex_normals"),Data.HasVertexNormals()); J->WriteValue(TEXT("has_triangle_groups"),Data.HasTriangleGroups()); J->WriteValue(TEXT("extended_polygroup_layer_count"),Data.HasAttributes()?Data.Attributes()->NumPolygroupLayers():0); const auto* Attributes=Data.HasAttributes()?Data.Attributes():nullptr; const int32 UVCount=Attributes?Attributes->NumUVLayers():0; J->WriteValue(TEXT("uv_channel_count"),UVCount); J->WriteValue(TEXT("normal_layer_count"),Attributes?Attributes->NumNormalLayers():0); J->WriteValue(TEXT("has_tangent_space"),Attributes && Attributes->HasTangentSpace()); J->WriteValue(TEXT("has_material_ids"),Attributes && Attributes->HasMaterialID()); J->WriteValue(TEXT("has_vertex_color_overlay"),Attributes && Attributes->HasPrimaryColors()); J->WriteValue(TEXT("vertex_color_elements"),Attributes && Attributes->HasPrimaryColors()?Attributes->PrimaryColors()->ElementCount():0); J->WriteArrayStart(TEXT("uv_channels")); for(int32 Layer=0;Layer<FMath::Min(UVCount,8);++Layer) { const auto* UV=Attributes->GetUVLayer(Layer); J->WriteObjectStart(); J->WriteValue(TEXT("index"),Layer); J->WriteValue(TEXT("element_count"),UV?UV->ElementCount():0); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("uv_channels_truncated"),UVCount>8); }); J->WriteObjectEnd(); }
 J->WriteArrayEnd(); J->WriteValue(TEXT("component_count"),Count); J->WriteValue(TEXT("truncated"),Count>128); J->WriteValue(TEXT("scope"),TEXT("Loaded current-world dynamic mesh components, native topology counts and attribute availability; up to8 UV-channel element counts. Global object iteration/custom component access work uncapped. No mesh copy, topology validation, geometry operation, collision rebuild, asset save or world mutation.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString GeometryScriptUtils::AddActorComponent(const FGeometryScriptReq& R)
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !R.bConfirm) throw std::runtime_error("Confirmed stopped editor world required"); auto* World=GEditor->GetEditorWorldContext().World(); if(!IsValid(World) || World->WorldType!=EWorldType::Editor || R.ActorPath.IsEmpty() || R.ActorPath.Len()>2048 || R.Name.IsEmpty() || R.Name.Len()>128 || FName(*R.Name).IsNone()) throw std::runtime_error("Current editor actor and bounded component name required"); for(const TCHAR C:R.Name) if(!FChar::IsAlnum(C) && C!=TEXT('_')) throw std::runtime_error("Component name requires letters/digits/underscore"); auto* Actor=FindObject<AActor>(nullptr,*R.ActorPath); if(!IsValid(Actor) || Actor->IsTemplate() || Actor->GetWorld()!=World || Actor->HasAnyFlags(RF_Transient)) throw std::runtime_error("Persistent current-world actor required"); if(FindObject<UObject>(Actor,*R.Name)) throw std::runtime_error("Component object name already exists on actor"); TArray<UDynamicMeshComponent*> Existing; Actor->GetComponents(Existing); if(Existing.Num()>=64) throw std::runtime_error("Actor Dynamic Mesh component count limit reached"); UDynamicMeshComponent* Component=nullptr;
 if(!R.bDryRun) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Add Dynamic Mesh Actor Component"))); Actor->Modify(); Component=NewObject<UDynamicMeshComponent>(Actor,FName(*R.Name),RF_Transactional); if(!IsValid(Component)) throw std::runtime_error("Native Dynamic Mesh component allocation failed"); Component->Modify(); Actor->AddInstanceComponent(Component); Component->OnComponentCreated(); if(Actor->GetRootComponent()) Component->SetupAttachment(Actor->GetRootComponent()); else Actor->SetRootComponent(Component); Component->RegisterComponent(); if(Component->GetOwner()!=Actor || Component->GetWorld()!=World || !Component->IsRegistered() || !Actor->GetInstanceComponents().Contains(Component)) throw std::runtime_error("Native component registration/ownership mismatch; inspect undo transaction"); Actor->MarkPackageDirty(); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("actor_path"),R.ActorPath); J->WriteValue(TEXT("component_name"),R.Name); J->WriteValue(TEXT("component_path"),GetPathNameSafe(Component)); J->WriteValue(TEXT("mesh_path"),Component?GetPathNameSafe(Component->GetDynamicMesh()):FString()); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("scope"),TEXT("Native instance Dynamic Mesh component creation/registration on existing actor, default empty mesh and attachment to actor root (or new root when absent). Registration/custom actor callbacks may affect world/subsystem state. No map save or explicit geometry operation; undo/resource lifecycle unverified.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString GeometryScriptUtils::AppendBox(const FGeometryScriptReq& R)
{
 if(!IsInGameThread() || !GEditor || !GEditor->Trans || GEditor->PlayWorld || !R.bConfirm) throw std::runtime_error("Confirmed stopped editor world with native transaction system required"); auto* World=GEditor->GetEditorWorldContext().World(); if(!IsValid(World) || World->WorldType!=EWorldType::Editor || R.ActorPath.IsEmpty() || R.ActorPath.Len()>2048 || R.ComponentPath.IsEmpty() || R.ComponentPath.Len()>2048 || R.MeshPath.IsEmpty() || R.MeshPath.Len()>2048) throw std::runtime_error("Bounded current-world mesh identities required"); auto* Component=FindObject<UDynamicMeshComponent>(nullptr,*R.ComponentPath); if(!IsValid(Component) || Component->IsTemplate() || Component->GetWorld()!=World || !IsValid(Component->GetOwner()) || Component->GetOwner()->GetPathName()!=R.ActorPath) throw std::runtime_error("Current mesh component/actor identity required"); auto* Mesh=Component->GetDynamicMesh(); if(!IsValid(Mesh) || Mesh->GetPathName()!=R.MeshPath || !Mesh->IsIn(Component)) throw std::runtime_error("Current owned dynamic mesh identity required");
 auto Finite=[](const FVector& V,double Bound) { return FMath::IsFinite(V.X) && FMath::IsFinite(V.Y) && FMath::IsFinite(V.Z) && FMath::Abs(V.X)<=Bound && FMath::Abs(V.Y)<=Bound && FMath::Abs(V.Z)<=Bound; }; if(!Finite(R.Dimensions,1.e6) || R.Dimensions.X<=0 || R.Dimensions.Y<=0 || R.Dimensions.Z<=0 || R.Transform.ContainsNaN() || !R.Transform.GetRotation().IsNormalized() || !Finite(R.Transform.GetTranslation(),1.e9) || !Finite(R.Transform.GetScale3D(),1000) || R.MaterialId<0 || R.MaterialId>255 || (R.Origin!=TEXT("Base") && R.Origin!=TEXT("Center"))) throw std::runtime_error("Positive bounded dimensions, finite transform/normalized rotation, material0..255 and Base/Center origin required"); const auto Scale=R.Transform.GetScale3D(); if(FMath::Abs(Scale.X)<1.e-6 || FMath::Abs(Scale.Y)<1.e-6 || FMath::Abs(Scale.Z)<1.e-6) throw std::runtime_error("Nonzero transform scale required"); int32 BeforeVertices=0,BeforeTriangles=0; Mesh->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { BeforeVertices=Data.VertexCount(); BeforeTriangles=Data.TriangleCount(); if(BeforeVertices>100000 || BeforeTriangles>100000 || Data.MaxVertexID()>200000 || Data.MaxTriangleID()>200000) throw std::runtime_error("Mesh exceeds primitive-edit copy budget"); }); int32 AfterVertices=BeforeVertices,AfterTriangles=BeforeTriangles;
 if(!R.bDryRun) { auto Before=MakeShared<UE::Geometry::FDynamicMesh3,ESPMode::ThreadSafe>(); Mesh->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { *Before=Data; }); auto* Working=NewObject<UDynamicMesh>(GetTransientPackage()); TStrongObjectPtr<UDynamicMesh> KeepAlive(Working); Working->SetMesh(UE::Geometry::FDynamicMesh3(*Before)); FGeometryScriptPrimitiveOptions Options; Options.MaterialID=R.MaterialId; Options.bFlipOrientation=R.bFlipOrientation; const auto Origin=R.Origin==TEXT("Center")?EGeometryScriptPrimitiveOriginMode::Center:EGeometryScriptPrimitiveOriginMode::Base; if(UGeometryScriptLibrary_MeshPrimitiveFunctions::AppendBox(Working,Options,R.Transform,R.Dimensions.X,R.Dimensions.Y,R.Dimensions.Z,0,0,0,Origin)!=Working) throw std::runtime_error("Native primitive operation failed"); auto After=MakeShared<UE::Geometry::FDynamicMesh3,ESPMode::ThreadSafe>(); Working->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { *After=Data; AfterVertices=Data.VertexCount(); AfterTriangles=Data.TriangleCount(); }); if(AfterTriangles<=BeforeTriangles || AfterTriangles>BeforeTriangles+100 || AfterVertices>BeforeVertices+100) throw std::runtime_error("Native box output count outside expected bounded growth"); FScopedTransaction Transaction(FText::FromString(TEXT("MCP Geometry Script Append Box"))); Component->GetOwner()->Modify(); Component->Modify(); Mesh->SetFlags(RF_Transactional); auto Change=MakeUnique<FMeshReplacementChange>(Before,After); Mesh->ApplyChange(Change.Get(),false); GUndo->StoreUndo(Mesh,MoveTemp(Change)); Mesh->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { if(Data.VertexCount()!=AfterVertices || Data.TriangleCount()!=AfterTriangles) throw std::runtime_error("Committed mesh count mismatch; inspect undo transaction"); }); Component->MarkPackageDirty(); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),R.ComponentPath); J->WriteValue(TEXT("mesh_path"),R.MeshPath); J->WriteValue(TEXT("before_vertices"),BeforeVertices); J->WriteValue(TEXT("before_triangles"),BeforeTriangles); J->WriteValue(TEXT("current_vertices"),AfterVertices); J->WriteValue(TEXT("current_triangles"),AfterTriangles); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("scope"),TEXT("Native unsubdivided box appended in component-local mesh coordinates on temporary copy, committed through mesh replacement command change for undo. Material slot compatibility/topology validity/visual result unverified. Mesh callbacks may rebuild rendering/collision or world state; no map/asset save. Copy/native callback work not strictly bounded.")); J->WriteObjectEnd(); J->Close(); return Result;
}

