 if(!R.bDryRun) { auto Before=MakeShared<UE::Geometry::FDynamicMesh3,ESPMode::ThreadSafe>(); Mesh->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { *Before=Data; }); auto* Working=NewObject<UDynamicMesh>(GetTransientPackage()); TStrongObjectPtr<UDynamicMesh> KeepAlive(Working); Working->SetMesh(UE::Geometry::FDynamicMesh3(*Before)); FGeometryScriptPrimitiveOptions Options; Options.MaterialID=R.MaterialId; Options.bFlipOrientation=R.bFlipOrientation; const auto Origin=R.Origin==TEXT("Center")?EGeometryScriptPrimitiveOriginMode::Center:EGeometryScriptPrimitiveOriginMode::Base; if(UGeometryScriptLibrary_MeshPrimitiveFunctions::AppendSphereLatLong(Working,Options,R.Transform,static_cast<float>(R.Radius),R.StepsPhi,R.StepsTheta,Origin)!=Working) throw std::runtime_error("Native primitive operation failed"); auto After=MakeShared<UE::Geometry::FDynamicMesh3,ESPMode::ThreadSafe>(); Working->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { *After=Data; AfterVertices=Data.VertexCount(); AfterTriangles=Data.TriangleCount(); }); if(AfterTriangles<=BeforeTriangles || AfterTriangles>BeforeTriangles+2*(R.StepsPhi+2)*(R.StepsTheta+2) || AfterVertices>BeforeVertices+(R.StepsPhi+2)*(R.StepsTheta+2)) throw std::runtime_error("Native sphere output count outside expected bounded growth"); FScopedTransaction Transaction(FText::FromString(TEXT("MCP Geometry Script Append Sphere"))); Component->GetOwner()->Modify(); Component->Modify(); Mesh->SetFlags(RF_Transactional); auto Change=MakeUnique<FMeshReplacementChange>(Before,After); Mesh->ApplyChange(Change.Get(),false); GUndo->StoreUndo(Mesh,MoveTemp(Change)); Mesh->ProcessMesh([&](const UE::Geometry::FDynamicMesh3& Data) { if(Data.VertexCount()!=AfterVertices || Data.TriangleCount()!=AfterTriangles) throw std::runtime_error("Committed mesh count mismatch; inspect undo transaction"); }); Component->MarkPackageDirty(); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),R.ComponentPath); J->WriteValue(TEXT("mesh_path"),R.MeshPath); J->WriteValue(TEXT("before_vertices"),BeforeVertices); J->WriteValue(TEXT("before_triangles"),BeforeTriangles); J->WriteValue(TEXT("current_vertices"),AfterVertices); J->WriteValue(TEXT("current_triangles"),AfterTriangles); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("scope"),TEXT("Native latitude-longitude sphere appended in component-local mesh coordinates on temporary copy, committed through mesh replacement command change for undo. Material slot compatibility/topology validity/visual result unverified. Mesh callbacks may rebuild rendering/collision or world state; no map/asset save. Copy/native callback work not strictly bounded.")); J->WriteObjectEnd(); J->Close(); return Result;
